<script setup>
import {ref,onMounted,watch} from 'vue'
import {api} from './api'
import {walletTranslations as translations} from './wallet-texts.js'
const emit=defineEmits(['dirty','saved'])
const props=defineProps({token:String,install:Boolean,admin:Boolean,language:{type:String,default:'ru'}})
const status=ref(null),error=ref(''),notice=ref(''),busy=ref(false),minutes=ref(30),primary=ref(1),standby=ref(7),peers=ref([]),fenced=ref(false),single=ref(false),confirmation=ref('')
const migrateLocal=ref(false),migrationConfirmation=ref(''),migrateVip=ref(false),vipConfirmation=ref('')
const diagnostics=ref(null)
const recovery=ref([]),recoveryId=ref(null),recoveryUid=ref('')
const tr=text=>translations[text]?.[props.language]||text
const reason=value=>tr(({nv9_uncertain_owner:"Наличные для восстановления",cash_during_vip:"Наличные во время VIP",late_click_payment:"Запоздавший Click"})[value]||value)
const endpoint=()=>props.install?'/api/commissioning/wallet':props.admin?'/api/admin/wallet':'/api/owner/wallet'
const request=(url,options={})=>api(url,{token:props.token,...options})
const post=(url,data={})=>request(url,{method:'POST',body:JSON.stringify(data)})
watch(()=>JSON.stringify([minutes.value,primary.value,standby.value,peers.value,fenced.value,single.value,confirmation.value,recoveryUid.value,migrateLocal.value,migrationConfirmation.value,migrateVip.value,vipConfirmation.value]),()=>{if(!busy.value)emit('dirty',true)},{flush:'sync'})
async function load(){diagnostics.value=null;status.value=await request(endpoint());const c=status.value.configuration;minutes.value=c.visit_timeout_minutes;primary.value=c.primary_post;standby.value=c.standby_post||7;peers.value=Object.entries(c.peer_urls).map(([post,url])=>({post:Number(post),url}));if(!peers.value.length)peers.value=[...new Set([1,7,c.local_post])].map(post=>({post,url:''}));emit('dirty',false)}
const diagnosticState=value=>tr(({'in-sync':'Данные совпадают','not-configured':'Кошелёк не настроен','single-copy':'Работа с одной копией','unavailable':'Один из узлов недоступен','authority-mismatch':'Роли узлов не совпадают','protocol-mismatch':'Обновите оба узла','pending':'Есть незавершённые операции','differs':'Данные различаются — повторите проверку'})[value]||value)
async function diagnose(){diagnostics.value=await request('/api/owner/wallet/diagnostics')}
async function loadRecovery(){recovery.value=(await request('/api/owner/wallet/recovery')).credits}
async function restore(){if(!recoveryId.value||!/^[0-9A-Fa-f]{4,64}$/.test(recoveryUid.value))throw Error('Выберите остаток и укажите UID денежной карты');await post('/api/owner/wallet/recovery/'+recoveryId.value,{uid:recoveryUid.value.toUpperCase()});await loadRecovery();recoveryId.value=null;recoveryUid.value='';emit('dirty',false);notice.value='Остаток переведён в кошелёк карты.'}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function setup(){const rows={};for(const p of peers.value){if(!Number.isInteger(p.post)||p.post<1||p.post>100||rows[p.post])throw Error('Проверьте номера постов: 1–100, без повторов');rows[p.post]=p.url.trim()}await post(props.install?endpoint():'/api/admin/wallet/setup',{primary_post:primary.value,standby_post:standby.value,peer_urls:rows,migrate_local_balances:migrateLocal.value,migration_confirmation:migrationConfirmation.value,migrate_local_vip:migrateVip.value,vip_migration_confirmation:vipConfirmation.value});await load();emit('saved');notice.value='Роли сохранены. Настройте второй узел и выполните синхронизацию на главном.'}
async function timeout(){await post('/api/owner/wallet/timeout',{visit_timeout_minutes:minutes.value});await load();notice.value='Время визита сохранено. Изменение действует для новых визитов.'}
async function promote(){await post('/api/owner/wallet/promote',{old_primary_fenced:fenced.value,single_node_confirmed:single.value,confirmation:confirmation.value});fenced.value=false;single.value=false;confirmation.value='';await load();notice.value='Этот пост назначен главным. До синхронизации данные имеют одну серверную копию.'}
async function sync(){await post('/api/owner/wallet/synchronize');await load();notice.value='Журналы сверены. Запись на главный и резервный восстановлена.'}
onMounted(()=>run(load))
</script>
<template>
<section class="card content wallet-settings"><h2>{{ tr("Общий кошелёк и резервный пост") }}</h2>
<p v-if="error" class="message error" role="alert">{{tr(error)}}</p><p v-if="notice" class="message success" role="status">{{tr(notice)}}</p>
<p v-if="busy" role="status">{{ tr("Проверка…") }}</p><button class="quiet" :disabled="busy" @click="run(load)">{{ tr("Обновить состояние") }}</button>
<template v-if="status"><p class="muted">{{tr('Мойка')}}: {{status.configuration.site_id||tr('не активирована')}} · {{tr('Этот пост')}}: {{status.configuration.local_post}}</p>
<template v-if="!status.configuration.enabled"><p>{{ tr("Главный хранит кошелёк, VIP и управляет Telegram. Резервный получает подтверждённые операции. Каждый пост нужно подключить к одной мойке.") }}</p>
<div class="fields"><label>{{ tr("Главный пост") }}<input v-model.number="primary" type="number" min="1" max="100"/></label><label>{{ tr("Резервный пост") }}<input v-model.number="standby" type="number" min="1" max="100"/></label></div>
<div v-for="(p,i) in peers" :key="i" class="wallet-peer"><label>{{ tr("Номер") }}<input v-model.number="p.post" type="number" min="1" max="100"/></label><label>{{ tr("Адрес поста") }}<input v-model="p.url" placeholder="http://10.10.10.8" inputmode="url"/></label><button class="quiet" :disabled="busy" @click="peers.splice(i,1)">{{ tr("Удалить") }}</button></div>
<label class="check"><input v-model="migrateLocal" type="checkbox"/>{{tr('Сохранить локальные остатки для переноса Owner')}}</label><p v-if="migrateLocal" class="muted">{{tr('Локальные денежные карты будут заблокированы, деньги сохранятся. После настройки Owner переносит каждую карту отдельно. Для VIP включите сохранение ниже.')}}</p><label v-if="migrateLocal">{{tr('Введите')}} MIGRATE LOCAL BALANCES POST {{status.configuration.local_post}}<input v-model="migrationConfirmation" autocomplete="off"/></label>
<label class="check"><input v-model="migrateVip" type="checkbox"/>{{tr('Сохранить локальные VIP для переноса Owner')}}</label><p v-if="migrateVip" class="muted">{{tr('VIP-карты будут заморожены. Профили, дневные допуски и VIP-остатки сохранятся. После установки Owner переносит их и завершает сверку всех постов.')}}</p><label v-if="migrateVip">{{tr('Введите')}} MIGRATE LOCAL VIP POST {{status.configuration.local_post}}<input v-model="vipConfirmation" autocomplete="off"/></label>
<div class="actions"><button class="quiet" :disabled="busy" @click="peers.push({post:peers.length+1,url:''})">{{ tr("Добавить пост") }}</button><button class="primary" :disabled="busy||!status.configuration.site_id" @click="run(setup)">{{ tr("Сохранить роли") }}</button></div>
</template>
<template v-else><dl class="wallet-status"><dt>{{ tr("Главный") }}</dt><dd>{{tr('Пост')}} {{status.configuration.primary_post}}</dd><dt>{{ tr("Резервный") }}</dt><dd>{{tr('Пост')}} {{status.configuration.standby_post}}</dd><dt>{{ tr("Режим") }}</dt><dd>{{status.configuration.single_node?tr('Одна серверная копия'):tr('Подтверждение на двух узлах')}}</dd><dt>{{ tr("Операции на сверку") }}</dt><dd>{{status.pending_count||0}}</dd><dt>{{ tr("Готовность резерва") }}</dt><dd>{{status.configuration.standby_ready?tr('Проверен'):tr('Требуется синхронизация')}}</dd></dl>
<template v-if="!install&&!admin"><div class="wallet-operation"><h3>{{tr('Состояние синхронизации')}}</h3><p>{{tr('Отметка готовности относится к последней синхронизации. Проверьте доступность и совпадение данных сейчас.')}}</p><button class="quiet" :disabled="busy" @click="run(diagnose)">{{tr('Проверить оба узла')}}</button><template v-if="diagnostics"><p role="status"><strong>{{diagnosticState(diagnostics.state)}}</strong></p><p class="muted">{{tr('Время проверки')}}: {{new Date(diagnostics.checked_at).toLocaleString(language==='uz'?'uz-UZ':language==='en'?'en-GB':'ru-RU')}}</p><div v-for="node in diagnostics.nodes" :key="node.post" class="wallet-node"><strong>{{tr('Пост')}} {{node.post}} · {{node.online?tr('Доступен'):tr('Недоступен')}}</strong><template v-if="node.online"><p>{{tr('Поколение')}}: {{node.proof.generation}} · {{tr('Операции')}}: {{node.proof.operation_count}} · {{tr('Операции на сверку')}}: {{node.proof.pending_count}}</p><p class="wallet-digest">{{tr('Журнал')}}: {{node.proof.journal_digest}}<br/>{{tr('Карты, квитанции и VIP')}}: {{node.proof.state_digest}}</p></template><p v-else>{{node.error}}</p></div><p class="muted">{{tr('Проверка не переключает роли. Данные могут измениться между снимками; при различии повторите проверку.')}}</p></template></div><label>{{ tr("Завершать визит через, минут") }}<input v-model.number="minutes" type="number" min="1" max="1440"/></label><p class="muted">{{ tr("По умолчанию 30 минут после возврата остатка. Повторное прикладывание до этого срока не обновляет бесплатную паузу.") }}</p><button class="primary" :disabled="busy||status.role!=='primary'" @click="run(timeout)">{{ tr("Сохранить время") }}</button>
<div v-if="status.role==='primary'" class="wallet-operation"><h3>{{ tr("Восстановить резервирование") }}</h3><p>{{ tr("Включите второй узел. Он станет резервным; главным автоматически не станет.") }}</p><button class="primary" :disabled="busy" @click="run(sync)">{{ tr("Синхронизировать и проверить") }}</button></div>
<div v-if="status.role==='standby'" class="wallet-operation"><h3>{{ tr("Назначить этот пост главным") }}</h3><p>{{ tr("Сначала физически отключите прежний главный от питания или сети. Если пропала только связь, оба узла могут продолжать работу.") }}</p><label class="check"><input v-model="fenced" type="checkbox"/>{{ tr("Прежний главный отключён от операций") }}</label><label class="check"><input v-model="single" type="checkbox"/>{{ tr("Принимаю работу с одной серверной копией до восстановления резерва") }}</label><label>{{tr('Введите')}} PROMOTE POST {{status.configuration.local_post}}<input v-model="confirmation" autocomplete="off"/></label><button class="primary" :disabled="busy||!fenced||!single||!status.configuration.standby_ready||confirmation!=='PROMOTE POST '+status.configuration.local_post" @click="run(promote)">{{ tr("Подтвердить переключение") }}</button></div>
<div class="wallet-operation"><h3>{{ tr("Восстановление денег") }}</h3><p>{{ tr("Запоздавшие платежи без привязанной карты и наличные во время VIP сохраняются отдельно. Проверив клиента и платёж, переведите остаток на его денежную карту. Повтор после сбоя допускается только на ту же карту.") }}</p><button class="quiet" :disabled="busy" @click="run(loadRecovery)">{{ tr("Показать сохранённые остатки") }}</button><div v-for="r in recovery" :key="r.id" class="wallet-operation"><strong>#{{r.id}} · {{Number(r.amount_sum).toLocaleString('ru-RU')}} so‘m</strong><p>{{reason(r.reason)}} · {{r.target_uid||tr('Карта ещё не указана')}}</p><button class="quiet" :disabled="busy" @click="recoveryId=r.id;recoveryUid=r.target_uid||''">{{ tr("Выбрать") }}</button></div><template v-if="recoveryId"><label>{{ tr("UID денежной карты") }}<input v-model="recoveryUid" maxlength="64" autocomplete="off"/></label><button class="primary" :disabled="busy" @click="run(restore)">{{tr('Перевести остаток')}} #{{recoveryId}}</button></template></div>
</template>
</template></template>
</section>
</template>
<style scoped>
.wallet-node{margin-top:16px;padding:16px;border:1px solid var(--border);border-radius:8px}.wallet-digest{overflow-wrap:anywhere;font-family:monospace;font-size:13px}.wallet-settings{margin-top:24px;padding:28px 30px}.wallet-settings>p{line-height:1.6;margin:20px 0}.wallet-settings .fields{padding:0;margin:24px 0}.wallet-settings label{display:flex;flex-direction:column;gap:12px}.wallet-settings label.check{flex-direction:row;align-items:flex-start}.wallet-settings .actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px}.wallet-settings .wallet-operation>p{line-height:1.6;margin:16px 0}.wallet-settings .wallet-operation>label{max-width:640px}.wallet-settings h3{margin:0 0 16px}.wallet-peer{display:flex;gap:16px;align-items:end;margin:16px 0}.wallet-peer label:first-child{max-width:120px}.wallet-peer label:nth-child(2){flex:1}.wallet-status{display:grid;grid-template-columns:1fr 1fr;gap:12px}.wallet-status dd{margin:0;font-weight:600}.wallet-operation{border-top:1px solid var(--border);padding-top:24px;margin-top:24px}.wallet-operation label{margin-bottom:16px}@media(max-width:650px){.wallet-settings{padding:20px}.wallet-settings .fields{grid-template-columns:1fr}.wallet-status{grid-template-columns:1fr}.wallet-settings .wallet-operation>label{max-width:100%}.wallet-peer{flex-wrap:wrap}.wallet-peer label:nth-child(2){min-width:200px}}
</style>
